sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float segments;
uniform float rotation;
uniform float sourceAngle;
uniform float zoom;
uniform float spin;
uniform float mirrorSeg;
uniform float twist;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float2 d = coord - ctr;
    float r = length(d);
    float n = floor(segments + 0.5);
    float sa = 6.2831853 / n;
    float a = atan(d.y, d.x) + radians(rotation) + radians(spin) * time + twist * r / length(size);
    a = mod(a, sa);
    if (mirrorSeg > 0.5) a = abs(a - sa * 0.5);
    a += radians(sourceAngle);
    return fin(c, texT(ctr + float2(cos(a), sin(a)) * r / zoom), opacity);
}
